 now=sha(path)
 if now!=h:
  assert Path(path).name=='vpr_stdout.log' and Path(path).parent.name in ('bigkey','dsip','misex3');changes.append(dict(path=path,frozen=h,current=now,disposition='automatically overwritten native output; original prepare.log remains preserved'))
 else:bindings[path]=h
